import { StandardSchemaV1 } from '@standard-schema/spec';
import { OpenAPIV3_1 } from 'openapi-types';

type ToOpenAPISchemaContext = {
    components: OpenAPIV3_1.ComponentsObject;
    /**
     * Whether to describe what a schema accepts or what it outputs, which differ
     * for one that transforms or defaults its input. Defaults to `"input"`.
     */
    io?: "input" | "output";
    options?: Record<string, unknown>;
};
/** A named schema converts to a reference to its component. */
type SchemaOrReference = OpenAPIV3_1.SchemaObject | OpenAPIV3_1.ReferenceObject;
type ToOpenAPISchemaFn = (schema: StandardSchemaV1, context: ToOpenAPISchemaContext) => SchemaOrReference | Promise<SchemaOrReference>;

export type { SchemaOrReference as S, ToOpenAPISchemaFn as T, ToOpenAPISchemaContext as a };
